class Solution {
public:
    vector<int> arrayRankTransform(vector<int>& arr) {
        vector<int> sorted = arr;
        sort(sorted.begin(), sorted.end());
        unordered_map<int, int> rankMap;
        int r = 1;
        for (int x : sorted) {
            if (rankMap.count(x) == 0) {
                rankMap[x] = r++;
            }
        }
        vector<int> result;
        result.reserve(arr.size());
        for (int x : arr) {
            result.push_back(rankMap[x]);
        }
        return result;
    }
};
